ALTER TABLE public.social_post_comments ADD COLUMN IF NOT EXISTS parent_comment_id uuid NULL REFERENCES public.social_post_comments(id) ON DELETE CASCADE;
ALTER TABLE public.global_content_comments ADD COLUMN IF NOT EXISTS parent_comment_id uuid NULL REFERENCES public.global_content_comments(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_social_post_comments_parent ON public.social_post_comments(parent_comment_id,created_at) WHERE parent_comment_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_global_content_comments_parent ON public.global_content_comments(parent_comment_id,created_at) WHERE parent_comment_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.social_post_comment_reactions (comment_id uuid NOT NULL REFERENCES public.social_post_comments(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,reaction text NOT NULL CHECK (reaction IN ('like','love','care','haha','wow','sad','angry')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(comment_id,user_id));
CREATE TABLE IF NOT EXISTS public.global_content_comment_reactions (comment_id uuid NOT NULL REFERENCES public.global_content_comments(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,reaction text NOT NULL CHECK (reaction IN ('like','love','care','haha','wow','sad','angry')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(comment_id,user_id));
CREATE INDEX IF NOT EXISTS idx_social_comment_reactions_comment ON public.social_post_comment_reactions(comment_id);
CREATE INDEX IF NOT EXISTS idx_global_comment_reactions_comment ON public.global_content_comment_reactions(comment_id);
ALTER TABLE public.social_post_comment_reactions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.global_content_comment_reactions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.social_post_comment_reactions FROM anon,authenticated; REVOKE ALL ON public.global_content_comment_reactions FROM anon,authenticated; GRANT ALL ON public.social_post_comment_reactions TO service_role; GRANT ALL ON public.global_content_comment_reactions TO service_role;
CREATE OR REPLACE FUNCTION public.sync_global_comment_to_social() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE v_content uuid; v_post uuid; BEGIN IF TG_OP='DELETE' THEN v_content:=OLD.content_id; ELSE v_content:=NEW.content_id; END IF; SELECT id INTO v_post FROM public.social_posts WHERE source_type='news' AND linked_entity_type='news' AND linked_entity_id=v_content LIMIT 1; IF v_post IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; IF TG_OP='DELETE' THEN DELETE FROM public.social_post_comments WHERE id=OLD.id; RETURN OLD; END IF; INSERT INTO public.social_post_comments(id,post_id,user_id,body,status,created_at,updated_at,parent_comment_id) VALUES(NEW.id,v_post,NEW.user_id,NEW.body,NEW.status,NEW.created_at,NEW.updated_at,NEW.parent_comment_id) ON CONFLICT(id) DO UPDATE SET body=EXCLUDED.body,status=EXCLUDED.status,updated_at=EXCLUDED.updated_at,parent_comment_id=EXCLUDED.parent_comment_id; RETURN NEW; END; $$;
UPDATE public.social_post_comments s SET parent_comment_id=g.parent_comment_id FROM public.global_content_comments g JOIN public.social_posts p ON p.source_type='news' AND p.linked_entity_type='news' AND p.linked_entity_id=g.content_id WHERE s.id=g.id AND s.post_id=p.id AND s.parent_comment_id IS DISTINCT FROM g.parent_comment_id;
CREATE OR REPLACE FUNCTION public.sync_global_comment_reaction_to_social() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE v_comment uuid; v_user uuid; BEGIN IF TG_OP='DELETE' THEN v_comment:=OLD.comment_id; v_user:=OLD.user_id; ELSE v_comment:=NEW.comment_id; v_user:=NEW.user_id; END IF; IF NOT EXISTS(SELECT 1 FROM public.social_post_comments c JOIN public.social_posts p ON p.id=c.post_id WHERE c.id=v_comment AND p.source_type='news' AND p.linked_entity_type='news') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; IF TG_OP='DELETE' THEN DELETE FROM public.social_post_comment_reactions WHERE comment_id=v_comment AND user_id=v_user; RETURN OLD; END IF; INSERT INTO public.social_post_comment_reactions(comment_id,user_id,reaction,created_at,updated_at) VALUES(NEW.comment_id,NEW.user_id,NEW.reaction,NEW.created_at,NEW.updated_at) ON CONFLICT(comment_id,user_id) DO UPDATE SET reaction=EXCLUDED.reaction,updated_at=EXCLUDED.updated_at; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS trg_sync_global_comment_reaction_to_social ON public.global_content_comment_reactions; CREATE TRIGGER trg_sync_global_comment_reaction_to_social AFTER INSERT OR UPDATE OR DELETE ON public.global_content_comment_reactions FOR EACH ROW EXECUTE FUNCTION public.sync_global_comment_reaction_to_social();
INSERT INTO public.social_post_comment_reactions(comment_id,user_id,reaction,created_at,updated_at) SELECT r.comment_id,r.user_id,r.reaction,r.created_at,r.updated_at FROM public.global_content_comment_reactions r JOIN public.social_post_comments c ON c.id=r.comment_id JOIN public.social_posts p ON p.id=c.post_id AND p.source_type='news' AND p.linked_entity_type='news' ON CONFLICT(comment_id,user_id) DO UPDATE SET reaction=EXCLUDED.reaction,updated_at=EXCLUDED.updated_at;
CREATE OR REPLACE FUNCTION public.get_global_content_comments_v2(p_content_id uuid) RETURNS TABLE(id uuid,parent_comment_id uuid,user_id uuid,body text,created_at timestamptz,author_name text,author_avatar text,can_delete boolean,reaction_count integer,reaction_breakdown jsonb,current_reaction text,reply_count integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='public' AS $$ SELECT cm.id,cm.parent_comment_id,cm.user_id,cm.body,cm.created_at,COALESCE(NULLIF(u.full_name,''),NULLIF(u.username,''),'DRIGHT user')::text,u.avatar_url,(cm.user_id=auth.uid()),(SELECT count(*)::integer FROM public.global_content_comment_reactions r WHERE r.comment_id=cm.id),COALESCE((SELECT jsonb_object_agg(x.reaction,x.cnt) FROM (SELECT r.reaction,count(*)::integer cnt FROM public.global_content_comment_reactions r WHERE r.comment_id=cm.id GROUP BY r.reaction) x),'{}'::jsonb),(SELECT r.reaction FROM public.global_content_comment_reactions r WHERE r.comment_id=cm.id AND r.user_id=auth.uid()),(SELECT count(*)::integer FROM public.global_content_comments rc WHERE rc.parent_comment_id=cm.id AND rc.status='visible') FROM public.global_content_comments cm JOIN public.global_announcements c ON c.id=cm.content_id LEFT JOIN public.users u ON u.id=cm.user_id WHERE auth.uid() IS NOT NULL AND cm.content_id=p_content_id AND cm.status='visible' AND c.is_active=true AND (c.content_kind='news' OR c.show_in_news=true) ORDER BY cm.created_at ASC; $$;
CREATE OR REPLACE FUNCTION public.get_social_post_comments_v2(p_post_id uuid) RETURNS TABLE(id uuid,parent_comment_id uuid,user_id uuid,body text,created_at timestamptz,author_name text,author_avatar text,can_delete boolean,reaction_count integer,reaction_breakdown jsonb,current_reaction text,reply_count integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='public' AS $$ DECLARE v_uid uuid:=auth.uid(); BEGIN IF v_uid IS NULL OR NOT public.social_can_view_post(p_post_id,v_uid) THEN RAISE EXCEPTION 'Post unavailable'; END IF; RETURN QUERY SELECT c.id,c.parent_comment_id,c.user_id,c.body,c.created_at,COALESCE(NULLIF(u.full_name,''),NULLIF(u.username,''),'DRIGHT User')::text,u.avatar_url,(c.user_id=v_uid OR (p.author_id=v_uid AND p.source_type<>'news')),(SELECT count(*)::integer FROM public.social_post_comment_reactions r WHERE r.comment_id=c.id),COALESCE((SELECT jsonb_object_agg(x.reaction,x.cnt) FROM (SELECT r.reaction,count(*)::integer cnt FROM public.social_post_comment_reactions r WHERE r.comment_id=c.id GROUP BY r.reaction) x),'{}'::jsonb),(SELECT r.reaction FROM public.social_post_comment_reactions r WHERE r.comment_id=c.id AND r.user_id=v_uid),(SELECT count(*)::integer FROM public.social_post_comments rc WHERE rc.parent_comment_id=c.id AND rc.status='visible') FROM public.social_post_comments c JOIN public.users u ON u.id=c.user_id JOIN public.social_posts p ON p.id=c.post_id WHERE c.post_id=p_post_id AND c.status='visible' AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE (b.blocker_id=v_uid AND b.blocked_id=c.user_id) OR (b.blocker_id=c.user_id AND b.blocked_id=v_uid)) ORDER BY c.created_at ASC; END; $$;
CREATE OR REPLACE FUNCTION public.add_global_content_reply(p_content_id uuid,p_parent_comment_id uuid,p_body text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE v_uid uuid:=auth.uid(); v_body text:=trim(COALESCE(p_body,'')); v_id uuid; v_count integer; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF char_length(v_body) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reply must be 1 to 2000 characters'; END IF; IF NOT EXISTS(SELECT 1 FROM public.global_announcements WHERE id=p_content_id AND is_active=true AND comments_enabled=true AND (content_kind='news' OR show_in_news=true)) THEN RAISE EXCEPTION 'Comments are disabled for this post'; END IF; IF NOT EXISTS(SELECT 1 FROM public.global_content_comments WHERE id=p_parent_comment_id AND content_id=p_content_id AND status='visible') THEN RAISE EXCEPTION 'Parent comment not found'; END IF; INSERT INTO public.global_content_comments(content_id,user_id,body,parent_comment_id) VALUES(p_content_id,v_uid,v_body,p_parent_comment_id) RETURNING id INTO v_id; SELECT count(*)::integer INTO v_count FROM public.global_content_comments WHERE content_id=p_content_id AND status='visible'; RETURN jsonb_build_object('comment_id',v_id,'comment_count',v_count,'parent_comment_id',p_parent_comment_id); END; $$;
CREATE OR REPLACE FUNCTION public.add_social_post_reply(p_post_id uuid,p_parent_comment_id uuid,p_body text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE v_uid uuid:=auth.uid(); v_body text:=trim(COALESCE(p_body,'')); v_id uuid; v_count integer; v_news uuid; v_author uuid; BEGIN IF v_uid IS NULL OR NOT public.social_can_view_post(p_post_id,v_uid) THEN RAISE EXCEPTION 'Post unavailable'; END IF; SELECT linked_entity_id INTO v_news FROM public.social_posts WHERE id=p_post_id AND source_type='news' AND linked_entity_type='news'; IF v_news IS NOT NULL THEN RETURN public.add_global_content_reply(v_news,p_parent_comment_id,p_body); END IF; IF char_length(v_body) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reply must be 1 to 2000 characters'; END IF; IF NOT EXISTS(SELECT 1 FROM public.social_posts WHERE id=p_post_id AND comments_enabled=true) THEN RAISE EXCEPTION 'Comments are disabled'; END IF; IF NOT EXISTS(SELECT 1 FROM public.social_post_comments WHERE id=p_parent_comment_id AND post_id=p_post_id AND status='visible') THEN RAISE EXCEPTION 'Parent comment not found'; END IF; INSERT INTO public.social_post_comments(post_id,user_id,body,parent_comment_id) VALUES(p_post_id,v_uid,v_body,p_parent_comment_id) RETURNING id INTO v_id; SELECT count(*)::integer INTO v_count FROM public.social_post_comments WHERE post_id=p_post_id AND status='visible'; SELECT user_id INTO v_author FROM public.social_post_comments WHERE id=p_parent_comment_id; IF v_author IS NOT NULL AND v_author<>v_uid THEN INSERT INTO public.social_notifications(user_id,actor_id,notification_type,entity_type,entity_id,metadata) VALUES(v_author,v_uid,'social_reply','social_post',p_post_id,jsonb_build_object('comment_id',v_id,'parent_comment_id',p_parent_comment_id)); END IF; RETURN jsonb_build_object('comment_id',v_id,'comment_count',v_count,'parent_comment_id',p_parent_comment_id); END; $$;
CREATE OR REPLACE FUNCTION public.set_global_content_comment_reaction(p_comment_id uuid,p_reaction text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE v_uid uuid:=auth.uid(); v_current text; v_count integer; v_breakdown jsonb; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF p_reaction NOT IN ('like','love','care','haha','wow','sad','angry') THEN RAISE EXCEPTION 'Invalid reaction'; END IF; IF NOT EXISTS(SELECT 1 FROM public.global_content_comments c JOIN public.global_announcements g ON g.id=c.content_id WHERE c.id=p_comment_id AND c.status='visible' AND g.is_active=true AND (g.content_kind='news' OR g.show_in_news=true)) THEN RAISE EXCEPTION 'Comment unavailable'; END IF; SELECT reaction INTO v_current FROM public.global_content_comment_reactions WHERE comment_id=p_comment_id AND user_id=v_uid FOR UPDATE; IF v_current=p_reaction THEN DELETE FROM public.global_content_comment_reactions WHERE comment_id=p_comment_id AND user_id=v_uid; v_current:=NULL; ELSE INSERT INTO public.global_content_comment_reactions(comment_id,user_id,reaction) VALUES(p_comment_id,v_uid,p_reaction) ON CONFLICT(comment_id,user_id) DO UPDATE SET reaction=EXCLUDED.reaction,updated_at=now(); v_current:=p_reaction; END IF; SELECT count(*)::integer INTO v_count FROM public.global_content_comment_reactions WHERE comment_id=p_comment_id; SELECT COALESCE(jsonb_object_agg(x.reaction,x.cnt),'{}'::jsonb) INTO v_breakdown FROM (SELECT reaction,count(*)::integer cnt FROM public.global_content_comment_reactions WHERE comment_id=p_comment_id GROUP BY reaction) x; RETURN jsonb_build_object('reaction',v_current,'reaction_count',v_count,'reaction_breakdown',COALESCE(v_breakdown,'{}'::jsonb)); END; $$;
CREATE OR REPLACE FUNCTION public.set_social_comment_reaction(p_comment_id uuid,p_reaction text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE v_uid uuid:=auth.uid(); v_current text; v_count integer; v_breakdown jsonb; v_news boolean; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; SELECT EXISTS(SELECT 1 FROM public.global_content_comments WHERE id=p_comment_id) INTO v_news; IF v_news THEN RETURN public.set_global_content_comment_reaction(p_comment_id,p_reaction); END IF; IF p_reaction NOT IN ('like','love','care','haha','wow','sad','angry') THEN RAISE EXCEPTION 'Invalid reaction'; END IF; IF NOT EXISTS(SELECT 1 FROM public.social_post_comments c WHERE c.id=p_comment_id AND c.status='visible' AND public.social_can_view_post(c.post_id,v_uid)) THEN RAISE EXCEPTION 'Comment unavailable'; END IF; SELECT reaction INTO v_current FROM public.social_post_comment_reactions WHERE comment_id=p_comment_id AND user_id=v_uid FOR UPDATE; IF v_current=p_reaction THEN DELETE FROM public.social_post_comment_reactions WHERE comment_id=p_comment_id AND user_id=v_uid; v_current:=NULL; ELSE INSERT INTO public.social_post_comment_reactions(comment_id,user_id,reaction) VALUES(p_comment_id,v_uid,p_reaction) ON CONFLICT(comment_id,user_id) DO UPDATE SET reaction=EXCLUDED.reaction,updated_at=now(); v_current:=p_reaction; END IF; SELECT count(*)::integer INTO v_count FROM public.social_post_comment_reactions WHERE comment_id=p_comment_id; SELECT COALESCE(jsonb_object_agg(x.reaction,x.cnt),'{}'::jsonb) INTO v_breakdown FROM (SELECT reaction,count(*)::integer cnt FROM public.social_post_comment_reactions WHERE comment_id=p_comment_id GROUP BY reaction) x; RETURN jsonb_build_object('reaction',v_current,'reaction_count',v_count,'reaction_breakdown',COALESCE(v_breakdown,'{}'::jsonb)); END; $$;
REVOKE ALL ON FUNCTION public.sync_global_comment_reaction_to_social() FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.get_global_content_comments_v2(uuid) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.get_social_post_comments_v2(uuid) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.add_global_content_reply(uuid,uuid,text) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.add_social_post_reply(uuid,uuid,text) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.set_global_content_comment_reaction(uuid,text) FROM PUBLIC,anon; REVOKE ALL ON FUNCTION public.set_social_comment_reaction(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_global_content_comments_v2(uuid),public.get_social_post_comments_v2(uuid),public.add_global_content_reply(uuid,uuid,text),public.add_social_post_reply(uuid,uuid,text),public.set_global_content_comment_reaction(uuid,text),public.set_social_comment_reaction(uuid,text) TO authenticated,service_role;